import numpy as np

def analyze_grid(grid):
    """Analyze potential transformations"""
    coords = {}
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            coords[(r, c)] = val

    # Find connected components of 3s
    visited = set()
    components = []

    directions = [(0,1), (1,0), (-1,0), (0,-1)]

    def bfs(start):
        component = set()
        queue = [start]
        component.add(start)

        while queue:
            r, c = queue.pop(0)
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if (nr, nc) not in visited and (nr, nc) in coords and coords[(nr, nc)] == 3:
                    visited.add((nr, nc))
                    component.add((nr, nc))
                    queue.append((nr, nc))
        return component

    for (r, c), v in coords.items():
        if v == 3 and (r, c) not in visited:
            component = bfs((r, c))
            components.append(component)
            visited.update(component)

    print(f"Found {len(components)} connected components of 3s")
    for i, comp in enumerate(components):
        print(f"  Component {i}: {len(comp)} cells")

